// Builds lib/i18n/legal/verification.generated.ts from the two drafts in
// docs/legal (the text the lawyer reviews), so the site shows exactly that
// text. Run after editing a draft:
//   node scripts/legal/build-verification-texts.mjs
// With --check it only reports whether the generated file is up to date
// (used by tests/legal-verification-texts.test.mjs).
//
// Draft format, per language: "## <Language>", then "### <section title>",
// then paragraphs and lists until "---" or the next "## ". Supported inside a
// section: paragraphs, "- " items, two-space nested "- " or "1. " items, and a
// two-space indented paragraph that closes the previous item. "**bold**" is
// kept as is (the page renders it).
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const OUT = join(ROOT, 'lib/i18n/legal/verification.generated.ts');
const LANGS = { Italiano: 'it', English: 'en', 'Español': 'es', 'Français': 'fr' };

function section(markdown, language) {
  const start = markdown.indexOf(`\n## ${language}\n`);
  if (start < 0) throw new Error(`missing "## ${language}"`);
  const rest = markdown.slice(start + language.length + 5);
  const end = rest.search(/\n---\n|\n## /);
  const body = (end < 0 ? rest : rest.slice(0, end)).trim().split('\n');
  const heading = body.shift();
  if (!heading?.startsWith('### ')) throw new Error(`${language}: expected a "### " title`);
  return { title: heading.slice(4).trim(), blocks: blocks(body, language) };
}

function blocks(lines, language) {
  const out = [];
  let paragraph = [];
  let list = null;
  let pendingAfter = false;
  const flushParagraph = () => {
    if (paragraph.length) out.push(paragraph.join(' '));
    paragraph = [];
  };
  const flushList = () => {
    if (list) out.push({ list });
    list = null;
  };
  const last = () => list[list.length - 1];
  const asObject = () => {
    const item = last();
    if (typeof item === 'string') list[list.length - 1] = { text: item };
    return list[list.length - 1];
  };
  for (const raw of lines) {
    const line = raw.replace(/\s+$/, '');
    if (!line) {
      flushParagraph();
      pendingAfter = !!list;
      continue;
    }
    const top = /^- (.*)$/.exec(line);
    const nested = /^ {2}(?:- |(\d+\. ))(.*)$/.exec(line);
    const indented = /^ {2}(\S.*)$/.exec(line);
    if (top) {
      flushParagraph();
      list ??= [];
      list.push(top[1]);
      pendingAfter = false;
    } else if (nested) {
      if (!list) throw new Error(`${language}: nested item without a parent: ${line}`);
      const item = asObject();
      (item.list ??= []).push(`${nested[1] ?? ''}${nested[2]}`);
    } else if (indented && list && pendingAfter) {
      const item = asObject();
      item.after = item.after ? `${item.after} ${indented[1]}` : indented[1];
    } else {
      flushList();
      paragraph.push(line.trim());
      pendingAfter = false;
    }
  }
  flushParagraph();
  flushList();
  return out;
}

export function build() {
  const privacy = readFileSync(join(ROOT, 'docs/legal/DRAFT_privacy-professional-verification.md'), 'utf8');
  const terms = readFileSync(join(ROOT, 'docs/legal/DRAFT_terms-professional-verification.md'), 'utf8');
  const texts = {};
  for (const [language, code] of Object.entries(LANGS)) {
    texts[code] = { privacy: section(privacy, language), terms: section(terms, language) };
  }
  return `// GENERATED by scripts/legal/build-verification-texts.mjs from
// docs/legal/DRAFT_privacy-professional-verification.md and
// docs/legal/DRAFT_terms-professional-verification.md. Do not edit by hand:
// edit the drafts and run the script. Placeholders ({{...}}) are filled from
// lib/i18n/legal/verificationValues.ts, and nothing is shown on the site until
// every value is set and the legal review is approved there.
import type { AppLang } from '@/lib/i18n/uiStrings';
import type { LegalSection } from './types';

export const VERIFICATION_TEXTS: Record<AppLang, { privacy: LegalSection; terms: LegalSection }> = ${JSON.stringify(texts, null, 2)};
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const next = build();
  if (process.argv.includes('--check')) {
    let current = '';
    try {
      current = readFileSync(OUT, 'utf8');
    } catch {}
    if (current !== next) {
      console.error('lib/i18n/legal/verification.generated.ts is out of date: run node scripts/legal/build-verification-texts.mjs');
      process.exit(1);
    }
    console.log('up to date');
  } else {
    writeFileSync(OUT, next);
    console.log(`wrote ${OUT}`);
  }
}
